def entropy(ys):
 n=len(ys)
 if not n:return 0
 ct=Counter(ys)
 return -sum(v/n*math.log2(v/n) for v in ct.values())
def fit_tree(rows,depth):
 ys=[y for _,x,y in rows]
 pred=Counter(ys).most_common(1)[0][0]
 if depth==0 or len(set(ys))==1 or len(rows)<4:return ('leaf',pred)
 base=entropy(ys); best=None
 for j in range(len(rows[0][1])):
  vals=set(x[j] for _,x,y in rows)
  if len(vals)<2:continue
  groups={v:[q for q in rows if q[1][j]==v] for v in vals}
  gain=base-sum(len(q)/len(rows)*entropy([y for _,x,y in q]) for q in groups.values())
  if best is None or gain>best[0]:best=(gain,j,groups)
 if best is None or best[0]<=0:return ('leaf',pred)
 _,j,groups=best
 return ('node',j,{v:fit_tree(q,depth-1) for v,q in groups.items()},pred)
def predict_tree(t,x):
 if t[0]=='leaf':return t[1]
 _,j,ch,pred=t
 return predict_tree(ch[x[j]],x) if x[j] in ch else pred
